from modele import chapitre,E,Q,tableau
from pedagogie import page,sec,bloc

chapitre(19,'donnees','Données et enquêtes','4 · Données, hasard et instructions',
'Question · Recueil · Tableau · Lecture critique',
['Planifier une enquête et recueillir des données.','Consigner des observations et construire un tableau simple.','Lire des représentations, filtrer des données et argumenter un choix.'],
['Tableaux, diagrammes en barres, diagrammes circulaires et courbes du cours moyen.'],[
page(1,'Préparer une enquête',
bloc('savoirfaire',r'1. Formuler une question précise. 2. Choisir qui interroger ou quoi observer. 3. Recueillir les données : questionnaire, comptage ou mesures. 4. Les organiser dans un tableau. 5. Les représenter et les interpréter. 6. Répondre à la question, avec prudence.','Les étapes d’une enquête'),
bloc('definition',r'Le caractère étudié peut être une qualité (moyen de transport, couleur préférée) ou une quantité (temps de trajet, taille d’une plante). L’effectif d’une valeur est le nombre de fois où elle apparaît.'),
sec(2,'Mesurer et consigner des observations'),
bloc('exemple',r'24 élèves ont indiqué leur moyen de transport. On compte les réponses et on construit le tableau des effectifs ; le total contrôle le comptage.'+tableau(['Moyen de transport','à pied','vélo','bus','voiture','Total'],[['Effectif','9','4','8','3','24']])),
bloc('savoirfaire',r'Pour des mesures, on note la date, l’unité et l’instrument utilisé, puis on range les valeurs dans un tableau, une colonne par observation.','Consigner des mesures')),
page(3,'Lire tableaux et représentations',
r'@FIG:cours-graphiques@',
bloc('propriete',r'Un diagramme en barres compare des effectifs ; un diagramme circulaire montre la part de chaque catégorie dans le tout ; une courbe montre une évolution, souvent au cours du temps.'),
sec(4,'Filtrer des données et argumenter un choix'),
bloc('savoirfaire',r'Pour faire un choix, on garde seulement les lignes d’un tableau qui vérifient un premier critère (jour, prix…), puis on applique le critère suivant aux lignes restantes.','Filtrer'),
bloc('attention',r'Lire avec esprit critique : d’où viennent les données ? Combien de personnes ont été interrogées ? L’axe vertical commence-t-il à zéro ? Une conclusion ne vaut que pour les données recueillies.')),
],[
E('Le bon outil',r'Pour chaque question d’enquête, dire si l’on utilise plutôt un questionnaire, un comptage ou des mesures.'+Q(r'Quel est le sport préféré des élèves de la classe ?',r'Combien de véhicules passent devant le collège entre 8 h et 8 h 30 ?',r'Quelle est la taille des élèves de la classe ?'),r'1. Un $\res{\text{questionnaire}}$. 2. Un $\res{\text{comptage}}$, sur place. 3. Des $\res{\text{mesures}}$, avec une toise et une unité commune.','Se demander d’où vient l’information.','assert len(["questionnaire","comptage","mesures"])==3'),
E('Construire un tableau',r'Vingt élèves ont répondu à la question « Quel animal as-tu à la maison ? » : chat, chien, chat, poisson, aucun, chat, chien, aucun, chat, lapin, chien, chat, aucun, chat, poisson, chien, chat, aucun, lapin, chat. Construire le tableau des effectifs.',r'Chat : $\res8$ ; chien : $\res4$ ; aucun : $\res4$ ; poisson : $\res2$ ; lapin : $\res2$. Total : $8+4+4+2+2=20$, le compte est bon.','Compter chaque réponse, puis contrôler le total.','L="chat chien chat poisson aucun chat chien aucun chat lapin chien chat aucun chat poisson chien chat aucun lapin chat".split()\nassert [L.count(a) for a in ["chat","chien","aucun","poisson","lapin"]]==[8,4,4,2,2] and len(L)==20'),
E('Lire un diagramme en barres',r'Le diagramme indique le nombre de livres empruntés au CDI chaque jour. Quel jour a-t-on emprunté le plus de livres ? Combien de livres en tout dans la semaine ? Quel écart entre le jour le plus fort et le plus faible ?',r'Le $\res{\text{mercredi}}$, avec 35 livres. Total : $15+20+35+25+30=\res{125}$. Écart : $35-15=\res{20}$ livres.','Lire chaque hauteur sur l’axe gradué.','v=[15,20,35,25,30]\nassert max(v)==35 and v.index(35)==2 and sum(v)==125 and max(v)-min(v)==20',figure='don-3'),
E('Lire un diagramme circulaire',r'Le diagramme représente les 4 heures d’écran d’un adolescent un dimanche. Combien de temps a-t-il passé sur chaque activité ?',r'Vidéos : la moitié, $\res{2\text{ h}}$. Jeux : un quart, $\res{1\text{ h}}$. Messages : un quart, $\res{1\text{ h}}$.','Associer chaque secteur à une fraction du disque.','assert Rational(1,2)*4==2 and Rational(1,4)*4==1',figure='don-4'),
E('Lire une courbe',r'La courbe montre la température relevée dans une cour de récréation au cours d’une journée de printemps. Quelle est la température la plus élevée, et à quelle heure ? De combien la température a-t-elle augmenté entre 6 h et ce moment ?',r'Maximum : $\res{21\ ^\circ\mathrm{C}}$ à $\res{15\text{ h}}$. Hausse : $21-8=\res{13\ ^\circ\mathrm{C}}$.','Lire l’abscisse et l’ordonnée du point le plus haut.','v=[8,12,18,21,16,11]\nassert max(v)==21 and v.index(21)==3 and 21-8==13',figure='don-5'),
E('Relevé de mesures',r'Un plant de haricot mesure 2 cm la semaine 1, puis 5 cm, $9$ cm, $14{,}5$ cm et 17 cm les semaines suivantes. Présenter ces mesures dans un tableau. Entre quelles semaines a-t-il le plus grandi ?',tableau(['Semaine','1','2','3','4','5'],[['Taille (cm)','2','5','9','14,5','17']])+r'Croissances : 3 cm ; 4 cm ; $5{,}5$ cm ; $2{,}5$ cm. Il a le plus grandi entre les semaines $\res{3\text{ et }4}$.','Calculer les écarts d’une semaine à la suivante.','v=[2,5,9,Rational("14.5"),17]\nd=[v[k+1]-v[k] for k in range(4)]\nassert d==[3,4,Rational("5.5"),Rational("2.5")] and d.index(max(d))==2'),
E('Tableau à double entrée',r'Le tableau donne le moyen de transport des élèves de deux classes. Compléter les totaux. Combien d’élèves viennent à pied ? Combien d’élèves en tout ?'+tableau(['Classe','à pied','vélo','bus','Total'],[['6e A','10','4','12','…'],['6e B','8','6','11','…'],['Total','…','…','…','…']]),r'Totaux des lignes : 26 et 25. Totaux des colonnes : 18 ; 10 ; 23. À pied : $\res{18}$ élèves. En tout : $\res{51}$ élèves, et $26+25=18+10+23=51$.','Additionner en ligne et en colonne, puis contrôler.','assert 10+4+12==26 and 8+6+11==25 and 10+8==18 and 4+6==10 and 12+11==23 and 26+25==18+10+23==51'),
E('Filtrer pour choisir',r'Sami cherche un atelier le mercredi, à 10 € au plus, avec encore des places. Quels ateliers peut-il choisir ?'+tableau(['Atelier','Jour','Prix (€)','Places restantes'],[['Échecs','mercredi','8','3'],['Théâtre','mercredi','15','5'],['Robotique','samedi','9','2'],['Chorale','mercredi','0','0'],['Escalade','mercredi','9','4']]),r'Mercredi : échecs, théâtre, chorale, escalade. Prix au plus 10 € : échecs, chorale, escalade. Places restantes : $\res{\text{échecs et escalade}}$.','Appliquer les critères l’un après l’autre.','A=[("echecs","mercredi",8,3),("theatre","mercredi",15,5),("robotique","samedi",9,2),("chorale","mercredi",0,0),("escalade","mercredi",9,4)]\nassert [a[0] for a in A if a[1]=="mercredi" and a[2]<=10 and a[3]>0]==["echecs","escalade"]'),
E('Un graphique trompeur',r'Un magasin affiche ce diagramme : « Nos ventes explosent ! » Les ventes sont passées de 102 à 108 articles. Pourquoi le dessin est-il trompeur ?',r'L’axe vertical commence à 100 : la seconde barre paraît 4 fois plus haute, alors que les ventes n’ont augmenté que de $108-102=\res6$ articles, soit environ $\res{6\text{~\%}}$. Avec un axe partant de 0, les barres seraient presque égales.','Vérifier où commence l’axe vertical.','assert 108-102==6 and (108-100)==4*(102-100) and Rational(6,102)<Rational(6,100)',figure='don-9'),
E('Construire un diagramme',r'Construire le diagramme en barres du tableau suivant, avec une graduation de 2 en 2.'+tableau(['Sport','foot','danse','judo','natation'],[['Effectif','12','9','5','4']]),r'Les barres, en vert, montent à 12, 9, 5 et 4. La barre de la danse s’arrête entre les graduations 8 et 10.','Choisir l’échelle, puis tracer chaque barre.','assert [12,9,5,4]==[12,9,5,4] and 12%2==0',figure='don-10'),
E('Le gaspillage à la cantine',r'Les délégués pèsent le pain jeté à la cantine : $3{,}2$ kg lundi, $2{,}8$ kg mardi, $3{,}5$ kg jeudi et $2{,}5$ kg vendredi. Quelle masse de pain est jetée dans la semaine ? Le collège veut réduire ce gaspillage de 25~% : quelle masse viser ?',r'Total : $3{,}2+2{,}8+3{,}5+2{,}5=\res{12\ \mathrm{kg}}$. Une baisse de 25~%, c’est 3 kg de moins : objectif $\res{9\ \mathrm{kg}}$ par semaine.','Additionner, puis appliquer un pourcentage.','assert Rational("3.2")+Rational("2.8")+Rational("3.5")+Rational("2.5")==12 and 12-Rational(25,100)*12==9'),
E('Les insectes du jardin',r'Une classe a compté les insectes observés dans le jardin du collège. Quelles espèces ont été vues au moins 3 jours sur 5 ? Quelle espèce a été comptée le plus souvent en tout ?'+tableau(['Espèce','lun','mar','mer','jeu','ven'],[['Abeille','4','0','3','5','2'],['Coccinelle','0','1','0','2','0'],['Papillon','2','3','1','0','4'],['Fourmi','10','12','8','15','9'],['Sauterelle','0','0','1','0','0']]),r'Jours avec observation : abeille 4, coccinelle 2, papillon 4, fourmi 5, sauterelle 1. Au moins 3 jours : $\res{\text{abeille, papillon et fourmi}}$. La plus comptée : la fourmi, avec $\res{54}$ observations.','Filtrer selon le nombre de jours non nuls.','T={"abeille":[4,0,3,5,2],"coccinelle":[0,1,0,2,0],"papillon":[2,3,1,0,4],"fourmi":[10,12,8,15,9],"sauterelle":[0,0,1,0,0]}\nassert [k for k,v in T.items() if sum(1 for x in v if x>0)>=3]==["abeille","papillon","fourmi"] and max(T,key=lambda k:sum(T[k]))=="fourmi" and sum(T["fourmi"])==54'),
E('Le climat d’une ville',r'Le graphique donne, pour une ville, la température moyenne (courbe) et les précipitations (barres) de chaque mois. Quel est le mois le plus chaud ? Le plus sec ? Le plus pluvieux ? Que remarque-t-on en été ?',r'Le plus chaud : $\res{\text{juillet}}$ (23 °C). Le plus sec : $\res{\text{juillet}}$ (18 mm). Le plus pluvieux : $\res{\text{novembre}}$ (70 mm). En été, il fait chaud et il pleut peu.','Lire chaque représentation avec son propre axe.','t=[3,4,7,11,15,19,23,22,18,13,8,4]\np=[55,48,45,50,60,40,18,25,52,66,70,62]\nassert t.index(max(t))==6 and p.index(min(p))==6 and p.index(max(p))==10',figure='don-13'),
E('Planifier une enquête',r'La classe veut répondre à la question : « Combien de temps les élèves mettent-ils pour venir au collège ? » Décrire les étapes de l’enquête et proposer un tableau vide pour les résultats.',r'Population : les élèves de la classe. Recueil : un questionnaire où chacun note sa durée, en minutes. Tableau : trois colonnes, $\res{\text{moins de 10 min, de 10 à 20 min, plus de 20 min}}$, avec les effectifs et un total. Puis un diagramme en barres et une phrase de conclusion.','Suivre les six étapes du cours.','assert 3==3'),
E('Choisir un séjour',r'Une famille cherche un séjour au bord de la mer, de 5 jours au moins et à 400 € au plus. Lequel peut-elle choisir ?'+tableau(['Séjour','Prix (€)','Durée (jours)','Lieu'],[['Alpes','380','5','montagne'],['Bretagne','420','6','mer'],['Vendée','350','5','mer'],['Corse','520','7','mer'],['Landes','390','4','mer']]),r'Au bord de la mer : Bretagne, Vendée, Corse, Landes. À 400 € au plus : Vendée et Landes. Au moins 5 jours : seule la $\res{\text{Vendée}}$ convient.','Filtrer critère par critère.','S=[("Alpes",380,5,"montagne"),("Bretagne",420,6,"mer"),("Vendee",350,5,"mer"),("Corse",520,7,"mer"),("Landes",390,4,"mer")]\nassert [s[0] for s in S if s[3]=="mer" and s[1]<=400 and s[2]>=5]==["Vendee"]')
],reperes=['Planifier une enquête et recueillir des données','Construire un tableau de données','Lire tableaux, diagrammes et courbes','Filtrer et interpréter avec esprit critique'],deco='statistiques')

chapitre(20,'probabilites','Comprendre le hasard','4 · Données, hasard et instructions',
'Chances · Équiprobabilité · Fraction · Fréquence',
['Savoir qu’une probabilité est un nombre compris entre 0 et 1.','Calculer une probabilité dans une situation d’équiprobabilité.','Comparer les résultats d’essais répétés à une probabilité calculée.'],
['« a chances sur b » au CM2 ; fractions, décimaux, pourcentages.'],[
page(1,'Du langage des chances au nombre',
bloc('definition',r'Une expérience est aléatoire quand on connaît les résultats possibles, appelés issues, sans pouvoir prévoir lequel se produira. La probabilité d’un événement est un nombre compris entre 0 et 1 : 0 pour un événement impossible, 1 pour un événement certain.'),
r'@FIG:cours-echelle-proba@',
sec(2,'Recenser les possibilités et calculer'),
bloc('propriete',r'Quand toutes les issues ont la même chance de se produire, on parle d’équiprobabilité. La probabilité d’un événement est alors le quotient du nombre d’issues favorables par le nombre total d’issues : « $a$ chances sur $b$ » devient le nombre $\frac ab$.'),
bloc('exemple',r'Avec un dé équilibré à six faces, la probabilité d’obtenir 6 est $\frac16$ ; celle d’obtenir un nombre pair est $\frac36=\frac12$, car 2, 4 et 6 conviennent.')),
page(3,'Relier les écritures et comparer',
bloc('savoirfaire',r'Une probabilité peut s’écrire avec une fraction, un décimal ou un pourcentage : $\frac12=0{,}5=50$~% ; $\frac14=0{,}25=25$~%. Pour comparer deux probabilités, on les écrit sous la même forme.','Changer d’écriture'),
bloc('savoirfaire',r'Pour deux pièces lancées, un arbre ou un tableau recense les 4 issues PP, PF, FP et FF, qui sont équiprobables : obtenir une pile et une face a donc 2 chances sur 4.','Recenser deux étapes'),
sec(4,'Observer des essais répétés'),
bloc('definition',r'Quand on répète une expérience, la fréquence d’un résultat est le quotient de son nombre d’apparitions par le nombre d’essais.'),
r'@FIG:cours-frequences@',
bloc('propriete',r'Quand le nombre d’essais devient grand, la fréquence se rapproche en général de la probabilité. On ne peut pourtant jamais prévoir le résultat d’un essai : le hasard n’a pas de mémoire.')),
],[
E('De l’impossible au certain',r'On lance un dé équilibré à six faces. Donner la probabilité de chaque événement.'+Q(r'Obtenir 7.',r'Obtenir un nombre inférieur ou égal à 6.',r'Obtenir 6.',r'Obtenir un nombre pair.'),r'1. Impossible : $\res0$. 2. Certain : $\res1$. 3. $\res{\frac16}$. 4. $\frac36=\res{\frac12}$.','Compter les faces favorables parmi les 6.','assert Rational(0,6)==0 and Rational(6,6)==1 and Rational(3,6)==Rational(1,2)'),
E('Une urne',r'Une urne contient des boules indiscernables au toucher : 3 rouges, 5 bleues et 2 vertes. On tire une boule au hasard. Calculer la probabilité de tirer une boule rouge, bleue, verte, puis une boule qui n’est pas rouge.',r'10 boules en tout. Rouge : $\res{\frac3{10}}$ ; bleue : $\frac5{10}=\res{\frac12}$ ; verte : $\frac2{10}=\res{\frac15}$ ; pas rouge : $\res{\frac7{10}}$.','Issues favorables sur nombre total de boules.','assert Rational(3,10)+Rational(5,10)+Rational(2,10)==1 and 1-Rational(3,10)==Rational(7,10)',figure='hasard-2'),
E('Changer d’écriture',r'Écrire chaque probabilité sous les deux autres formes : $\frac14$ ; $\frac35$ ; $0{,}7$ ; 15~%.',r'$\frac14=\res{0{,}25}=\res{25\text{~\%}}$ ; $\frac35=\res{0{,}6}=\res{60\text{~\%}}$ ; $0{,}7=\res{\frac7{10}}=\res{70\text{~\%}}$ ; 15~% $=\res{\frac{15}{100}}=\res{0{,}15}$.','Passer par les centièmes.','assert Rational(1,4)==Rational(".25") and Rational(3,5)==Rational(".6") and Rational(".7")==Rational(7,10) and Rational(15,100)==Rational(".15")'),
E('La roue',r'La roue est partagée en 8 secteurs identiques numérotés de 1 à 8. On la fait tourner. Calculer la probabilité d’obtenir un nombre pair, un nombre supérieur ou égal à 6, puis un multiple de 3.',r'Pair : 2, 4, 6, 8, soit $\frac48=\res{\frac12}$. Au moins 6 : 6, 7, 8, soit $\res{\frac38}$. Multiple de 3 : 3 et 6, soit $\frac28=\res{\frac14}$.','Lister les issues favorables.','L=range(1,9)\nassert Rational(len([k for k in L if k%2==0]),8)==Rational(1,2) and Rational(len([k for k in L if k>=6]),8)==Rational(3,8) and Rational(len([k for k in L if k%3==0]),8)==Rational(1,4)',figure='hasard-4'),
E('Une pièce sans mémoire',r'Une pièce équilibrée vient de tomber trois fois de suite sur pile. Lucas pense que face a plus de chances de sortir au quatrième lancer. A-t-il raison ?',r'$\res{\text{Non}}$ : la pièce ne se souvient pas des lancers précédents. Au quatrième lancer, la probabilité d’obtenir face vaut toujours $\res{\frac12}$.','Chaque lancer recommence l’expérience.','assert Rational(1,2)==Rational(1,2)'),
E('Deux pièces',r'On lance deux pièces équilibrées. L’arbre recense les issues. Quelle est la probabilité d’obtenir deux piles ? Une pile et une face ?',r'4 issues équiprobables : PP, PF, FP, FF. Deux piles : $\res{\frac14}$. Une pile et une face : PF ou FP, soit $\frac24=\res{\frac12}$.','Compter les chemins de l’arbre.','I=[a+b for a in "PF" for b in "PF"]\nassert len(I)==4 and Rational(I.count("PP"),4)==Rational(1,4) and Rational(len([i for i in I if set(i)=={"P","F"}]),4)==Rational(1,2)',figure='hasard-6'),
E('Deux dés',r'On lance deux dés équilibrés et on additionne les résultats. Le tableau recense les 36 issues. Quelle est la probabilité d’obtenir une somme égale à 7 ? Égale à 12 ?',r'Somme 7 : six cases, en vert. Probabilité : $\frac6{36}=\res{\frac16}$. Somme 12 : une seule case, 6 et 6 : $\res{\frac1{36}}$.','Compter les cases favorables du tableau.','S=[a+b for a in range(1,7) for b in range(1,7)]\nassert Rational(S.count(7),36)==Rational(1,6) and Rational(S.count(12),36)==Rational(1,36)',figure='hasard-7'),
E('Fréquence et probabilité',r'Emma lance un dé 200 fois et obtient 36 fois le six. Calculer la fréquence du six, puis la comparer à la probabilité.',r'Fréquence : $\frac{36}{200}=\frac{18}{100}=\res{0{,}18}$. Probabilité : $\frac16\approx\res{0{,}17}$. Les deux nombres sont proches, sans être égaux : c’est normal.','Fréquence observée contre probabilité calculée.','assert Rational(36,200)==Rational(".18") and abs(Rational(1,6)-Rational(".17"))<Rational(1,200)'),
E('Deux urnes',r'L’urne A contient 2 boules rouges sur 5 boules ; l’urne B, 3 boules rouges sur 8. Dans quelle urne a-t-on le plus de chances de tirer une boule rouge ?',r'A : $\frac25=\res{0{,}4}$. B : $\frac38=\res{0{,}375}$. Les chances sont meilleures avec l’urne $\res{\text{A}}$, bien qu’elle contienne moins de boules rouges.','Comparer des probabilités, pas des effectifs.','assert Rational(2,5)==Rational(".4") and Rational(3,8)==Rational(".375") and Rational(2,5)>Rational(3,8)',figure='hasard-9'),
E('Une roue inégale',r'La roue comporte trois secteurs A, B et C. Tom dit : « Il y a trois secteurs, donc chacun a une chance sur trois. » A-t-il raison ?',r'$\res{\text{Non}}$ : les secteurs ne sont pas de même taille. A occupe la moitié de la roue, d’où une probabilité de $\res{\frac12}$ ; B et C occupent chacun un quart : $\res{\frac14}$ chacun.','Vérifier l’équiprobabilité avant de calculer.','assert Rational(180,360)==Rational(1,2) and Rational(90,360)==Rational(1,4)',figure='hasard-10'),
E('Le jeu de 32 cartes',r'On tire une carte au hasard dans un jeu de 32 cartes : 4 couleurs (cœur, carreau, trèfle, pique) de 8 cartes, dont un roi par couleur. Quelle est la probabilité de tirer un cœur ? Un roi ? Le roi de cœur ?',r'Cœur : $\frac8{32}=\res{\frac14}$. Roi : $\frac4{32}=\res{\frac18}$. Roi de cœur : $\res{\frac1{32}}$.','Compter les cartes favorables.','assert Rational(8,32)==Rational(1,4) and Rational(4,32)==Rational(1,8)'),
E('Le sac de bonbons',r'Un sac contient 20 bonbons. La probabilité de tirer un bonbon à la fraise est $0{,}35$. Combien y a-t-il de bonbons à la fraise ? On ajoute 5 bonbons à la fraise : quelle est la nouvelle probabilité, en pourcentage ?',r'$0{,}35\times20=\res7$ bonbons à la fraise. Ensuite : 12 bonbons à la fraise sur 25, soit $\frac{12}{25}=\frac{48}{100}=\res{48\text{~\%}}$.','Appliquer la probabilité au nombre total.','assert Rational(".35")*20==7 and Rational(12,25)==Rational(48,100)'),
E('La punaise',r'Une punaise lancée retombe pointe en haut ou pointe en bas ; les deux issues n’ont pas forcément la même chance. Une classe a réalisé $1\,000$ lancers et obtenu 620 fois « pointe en haut ». La courbe montre l’évolution de la fréquence. Quelle probabilité peut-on proposer ?',r'Fréquence finale : $\frac{620}{1\,000}=\res{0{,}62}$. Comme la fréquence se stabilise, on peut estimer la probabilité à environ $\res{0{,}62}$. On ne peut pas la calculer, car il n’y a pas équiprobabilité.','Utiliser la stabilisation des fréquences.','assert Rational(620,1000)==Rational(".62")',figure='hasard-13'),
E('Un jeu équitable ?',r'On lance deux dés et on additionne. Alice gagne si la somme vaut 7 ; Bob gagne si la somme vaut 2, 3 ou 12. Le jeu est-il équitable ? Ajouter à Bob une somme pour le rendre équitable.',r'Alice : 6 issues sur 36. Bob : $1+2+1=4$ issues. Le jeu n’est $\res{\text{pas équitable}}$. En ajoutant la somme 11 (2 issues) à Bob, il a aussi 6 chances sur 36 : le jeu devient équitable.','Compter les issues de chaque joueur.','S=[a+b for a in range(1,7) for b in range(1,7)]\nassert S.count(7)==6 and S.count(2)+S.count(3)+S.count(12)==4 and S.count(2)+S.count(3)+S.count(12)+S.count(11)==6'),
E('Vrai ou faux',r'Nina affirme : « Avec deux dés, obtenir 6 avec le premier dé et 6 avec le second est moins probable qu’obtenir 3 avec le premier et 5 avec le second. » A-t-elle raison ?',r'$\res{\text{Non}}$ : chacun de ces résultats correspond à une seule case du tableau des 36 issues. Ils ont la même probabilité, $\res{\frac1{36}}$.','Toutes les cases du tableau sont équiprobables.','assert Rational(1,36)==Rational(1,36)')
],reperes=['Probabilité entre 0 et 1','Calculer en situation d’équiprobabilité','Écritures et comparaisons','Fréquences et essais répétés'],deco='probabilites')

chapitre(21,'instructions','Instructions, répétitions et chemins','4 · Données, hasard et instructions',
'Entrée · Sortie · Séquence · Répétition · Chemin',
['Identifier une instruction, une séquence, une entrée et une sortie.','Exécuter et produire une séquence d’instructions, y compris répétée.','Programmer un chemin simple, avec ou sans machine.'],
['Déplacements codés ; programmes de calcul ; motifs évolutifs.'],[
page(1,'Instruction, séquence, entrée et sortie',
bloc('definition',r'Une instruction est un ordre élémentaire donné à une personne ou à une machine : « avancer de 2 cases », « ajouter 3 ». Une séquence d’instructions est une suite d’instructions exécutées dans l’ordre. Une entrée est une donnée fournie au programme ; une sortie est un résultat qu’il affiche.'),
r'@FIG:cours-blocs@',
sec(2,'Exécuter dans l’ordre et suivre les étapes'),
bloc('savoirfaire',r'On note la valeur obtenue après chaque instruction. Avec l’entrée 5 : $5\times3=15$, puis $15+4=19$. La sortie est 19.','Exécuter à la main'),
bloc('attention',r'L’ordre des instructions compte : « ajouter 4, puis multiplier par 3 » donne, avec l’entrée 5, $(5+4)\times3=27$, et non 19.')),
page(3,'Reconnaître et répéter une séquence',
bloc('definition',r'Une répétition, ou boucle, exécute plusieurs fois la même séquence. « Répéter 4 fois : avancer de 3 cases, tourner d’un quart de tour à gauche » trace un carré de 3 cases de côté.'),
bloc('savoirfaire',r'Pour répéter à la main, on note après chaque tour de boucle la position et l’orientation du personnage. On s’arrête après le nombre de tours annoncé.','Suivre une boucle'),
sec(4,'Coder un chemin simple'),
r'@FIG:cours-chemin@',
bloc('savoirfaire',r'On découpe le chemin en morceaux : avancer d’un certain nombre de cases, tourner d’un quart de tour à gauche ou à droite. Quand un même morceau revient plusieurs fois, on l’écrit avec une répétition.','Coder un chemin')),
],[
E('Instruction ou séquence ?',r'Classer en instructions et en séquences d’instructions : « avancer de 3 cases » ; « avancer de 1 case, tourner à gauche, avancer de 2 cases » ; « afficher le résultat » ; « ajouter 5, puis multiplier par 2 ».',r'Instructions : $\res{\text{« avancer de 3 cases » et « afficher le résultat »}}$. Séquences : les deux autres, formées de plusieurs instructions dans un ordre donné.','Compter les ordres élémentaires.','assert 2+2==4'),
E('Exécuter un programme',r'Exécuter le programme avec l’entrée 7, en notant la valeur après chaque bloc. Quelle est la sortie ?',r'$7\times2=14$ ; $14-3=11$ ; $11\times10=110$. Sortie : $\res{110}$.','Une ligne par instruction.','assert (7*2-3)*10==110',figure='ins-2'),
E('Entrée et sortie',r'Une machine presse des oranges : on lui donne le nombre d’oranges, chaque orange donne 8 cL de jus, puis la machine affiche la quantité de jus obtenue. Quelle est l’entrée ? La sortie ? Que s’affiche-t-il pour 6 oranges ?',r'Entrée : $\res{\text{le nombre d’oranges}}$. Sortie : $\res{\text{la quantité de jus}}$. Pour 6 oranges : $6\times8=\res{48\ \mathrm{cL}}$.','Repérer ce qui est donné et ce qui est affiché.','assert 6*8==48'),
E('Suivre un chemin',r'Le robot part de la case D, tourné vers la droite. Il exécute : avancer de 3 cases ; tourner à gauche ; avancer de 2 cases ; tourner à droite ; avancer de 2 cases. Sur quelle case, P, Q ou R, arrive-t-il ?',r'Le trajet est tracé en vert : le robot arrive 5 cases à droite et 2 cases au-dessus de D, sur la case $\res{\text{R}}$.','Suivre chaque instruction en notant l’orientation.','assert True',figure='ins-4'),
E('L’ordre compte',r'Avec l’entrée 5, exécuter le programme « ajouter 3, puis multiplier par 2 », puis le programme « multiplier par 2, puis ajouter 3 ». Comparer.',r'Premier : $(5+3)\times2=\res{16}$. Second : $5\times2+3=\res{13}$. Les mêmes instructions dans un autre ordre donnent une autre sortie.','Exécuter dans l’ordre écrit.','assert (5+3)*2==16 and 5*2+3==13'),
E('Répéter à la main',r'Le lutin part du point de départ, tourné vers la droite. Exécuter « répéter 3 fois : avancer de 2 cases, tourner d’un quart de tour à droite ». Où arrive-t-il, et dans quelle direction regarde-t-il ?',r'Tour 1 : 2 cases à droite, puis il se tourne vers le bas. Tour 2 : 2 cases vers le bas, puis vers la gauche. Tour 3 : 2 cases à gauche, puis vers le haut. Il arrive $\res{2\text{ cases sous le départ}}$, tourné $\res{\text{vers le haut}}$ (trajet en vert).','Noter position et orientation à chaque tour.','assert True',figure='ins-6'),
E('Écrire avec une boucle',r'Réécrire avec une répétition la séquence : avancer de 2 cases, tourner à gauche, avancer de 2 cases, tourner à gauche, avancer de 2 cases, tourner à gauche, avancer de 2 cases, tourner à gauche. Quelle figure obtient-on ?',r'« $\res{\text{Répéter 4 fois : avancer de 2 cases, tourner à gauche}}$ ». Le personnage trace un carré de 2 cases de côté et revient à son point de départ.','Repérer le morceau qui revient.','assert 4*2==8'),
E('Coder un chemin',r'Écrire un programme qui conduit le robot de la case D à la case A sans passer par les cases grisées. Il part tourné vers la droite.',r'Par exemple : avancer de 2 cases ; tourner à gauche ; avancer de 3 cases ; tourner à droite ; avancer de 3 cases. Ce chemin est tracé en vert ; d’autres chemins conviennent.','Découper le trajet en lignes droites.','assert True',figure='ins-8'),
E('Remonter un programme',r'Un programme multiplie l’entrée par 4, puis ajoute 2. La sortie est 50. Quelle était l’entrée ?',r'On remonte : $50-2=48$, puis $48:4=\res{12}$. Contrôle : $12\times4+2=50$.','Défaire les instructions à l’envers.','assert (50-2)//4==12 and 12*4+2==50'),
E('Le motif répété',r'Le lutin part du point de départ, tourné vers la droite. Exécuter « répéter 4 fois : avancer de 1 case, tourner à gauche, avancer de 1 case, tourner à droite ». Quelle figure trace-t-il ? Où arrive-t-il ?',r'Il trace un $\res{\text{escalier}}$ de 4 marches, en vert. Il arrive 4 cases à droite et 4 cases au-dessus du départ, tourné vers la droite.','Chaque tour de boucle ajoute une marche.','assert True',figure='ins-10'),
E('Le robot livreur',r'Le robot part de D, tourné vers la droite, et exécute : avancer de 2 ; tourner à gauche ; avancer de 3 ; tourner à droite ; avancer de 4 ; tourner à droite ; avancer de 1. Devant quelle maison s’arrête-t-il ?',r'Positions successives : 2 cases à droite, puis 3 cases vers le haut, puis 4 cases à droite, puis 1 case vers le bas. Il s’arrête devant la maison $\res{\text{B}}$ (trajet en vert).','Exécuter pas à pas.','assert True',figure='ins-11'),
E('Le polygone',r'Un lutin exécute « répéter 6 fois : avancer de 3 cm, tourner de $60^\circ$ à gauche ». Quelle figure trace-t-il ? Quel est son périmètre ?',r'Il tourne en tout de $6\times60=360^\circ$ et revient à son point de départ : il trace un $\res{\text{hexagone}}$ de 6 côtés égaux, en vert. Périmètre : $6\times3=\res{18\ \mathrm{cm}}$.','Additionner les angles de rotation.','assert 6*60==360 and 6*3==18',figure='ins-12'),
E('Le tableur',r'Dans un tableur, la cellule A1 contient 5 et la cellule A2 contient la formule « =A1+4 », recopiée vers le bas. Quel nombre s’affiche en A10 ? Dans quelle cellule lit-on 101 ?',r'Chaque cellule vaut 4 de plus que la précédente : A10 vaut $5+9\times4=\res{41}$. Pour 101 : $101-5=96$ et $96:4=24$ pas après A1, donc en $\res{\text{A25}}$.','Compter les pas de 4 depuis A1.','L=[5+4*k for k in range(30)]\nassert L[9]==41 and L.index(101)==24'),
E('Trouver l’erreur',r'Pour tracer un carré, Hugo a écrit : « répéter 3 fois : avancer de 4 cases, tourner à gauche ». Observer le tracé obtenu. Corriger le programme.',r'Le tracé n’a que trois côtés : le carré n’est pas fermé. Il faut $\res{\text{répéter 4 fois}}$ : avancer de 4 cases, tourner à gauche. Le côté manquant est en vert.','Comparer le tracé à la figure voulue.','assert True',figure='ins-14'),
E('Le plus court chemin',r'Le robot doit aller de D à A, tourné vers la droite au départ, sans traverser les cases grisées. Il avance case par case. Combien de cases parcourt-il au minimum ? Écrire un programme court avec une répétition.',r'A est 5 cases à droite et 5 cases plus haut : il faut au moins $5+5=\res{10}$ cases. Le programme « répéter 5 fois : avancer de 1, tourner à gauche, avancer de 1, tourner à droite » réalise ce minimum en évitant les obstacles (en vert).','Compter les déplacements indispensables.','assert 5+5==10',figure='ins-15')
],reperes=['Instruction, séquence, entrée et sortie','Exécuter un programme à la main','Répétitions','Coder un chemin'],deco='algorithmique')
